import re

VAR = re.compile(r'\(\s*([^\s()/]+)\s*/')


def sub_outside_quotes(text, fn):
    parts = re.split(r'("[^"]*")', text)
    for k in range(0, len(parts), 2):
        parts[k] = fn(parts[k])
    return ''.join(parts)


def node_bounds(g, pos):
    depth = 0
    inq = False
    i = pos - 1
    while i >= 0:
        c = g[i]
        if c == '"':
            inq = not inq
        elif not inq:
            if c == ')':
                depth += 1
            elif c == '(':
                if depth == 0:
                    break
                depth -= 1
        i -= 1
    if i < 0:
        return None
    start = i
    depth = 0
    inq = False
    j = start
    while j < len(g):
        c = g[j]
        if c == '"':
            inq = not inq
        elif not inq:
            if c == '(':
                depth += 1
            elif c == ')':
                depth -= 1
                if depth == 0:
                    return (start, j + 1)
        j += 1
    return None


def direct_text(node):
    out = []
    depth = 0
    inq = False
    for c in node:
        if c == '"':
            inq = not inq
        if not inq and c == '(':
            depth += 1
        elif not inq and c == ')':
            depth -= 1
        elif depth == 1:
            out.append(c)
    return ''.join(out)


def strip_singular(g):
    pat = re.compile(r'\s*:refer-number\s+singular\b')
    for m in reversed(list(pat.finditer(g))):
        b = node_bounds(g, m.start())
        if b is None:
            continue
        node = g[b[0]:b[1]]
        if ':refer-person' not in direct_text(node):
            g = g[:m.start()] + g[m.end():]
    return g


def fix_modal(doc):
    if ':modal' not in doc:
        return doc
    has_root = re.search(r'\(\s*root\s+:modal\s+author\s*\)', doc)
    doc = re.sub(r'\(\s*(?!root\b)[^\s()]+\s+:modal\s+author\s*\)\s*', '', doc)
    if not has_root:
        m = re.search(r':modal\s*\(\s*', doc)
        if m:
            doc = doc[:m.end()] + '(root :modal author) ' + doc[m.end():]
    return doc


def fix(text, n):
    i = text.find('# alignment:')
    j = text.find('# document level annotation:')
    if i < 0 or j < 0 or j < i:
        return text
