import re

VAR = re.compile(r'\(\s*([^\s()/]+)\s*/')


def sub_outside_quotes(text, fn):
    parts = re.split(r'("[^"]*")', text)
    for k in range(0, len(parts), 2):
        parts[k] = fn(parts[k])
    return ''.join(parts)


def node_bounds(g, pos):
    depth = 0
    inq = False
    i = pos - 1
    while i >= 0:
        c = g[i]
        if c == '"':
            inq = not inq
        elif not inq:
            if c == ')':
                depth += 1
            elif c == '(':
                if depth == 0:
                    break
                depth -= 1
        i -= 1
    if i < 0:
        return None
    start = i
    depth = 0
    inq = False
    j = start
    while j < len(g):
        c = g[j]
        if c == '"':
            inq = not inq
        elif not inq:
            if c == '(':
                depth += 1
            elif c == ')':
                depth -= 1
                if depth == 0:
                    return (start, j + 1)
        j += 1
    return None


def direct_text(node):
    out = []
    depth = 0
    inq = False
    for c in node:
        if c == '"':
            inq = not inq
        if not inq and c == '(':
            depth += 1
        elif not inq and c == ')':
            depth -= 1
        elif depth == 1:
